def split_record(s):
    if s == '':
        return ['']
    fields = []
    i = 0
    n = len(s)
    while True:
        if i < n and s[i] == '"':
            i += 1
            buf = []
            closed = False
            while i < n:
                c = s[i]
                if c == '"':
                    if i + 1 < n and s[i + 1] == '"':
                        buf.append('"')
                        i += 2
                    else:
                        i += 1
                        closed = True
                        break
                else:
                    buf.append(c)
                    i += 1
            if not closed:
                raise ValueError("unclosed quote")
            if i < n and s[i] != ';':
                raise ValueError("invalid character after closing quote")
            fields.append(''.join(buf))
            if i < n:
                i += 1
                if i == n:
                    fields.append('')
                    break
            else:
                break
        else:
            start = i
            while i < n and s[i] != ';':
                if s[i] == '"':
                    raise ValueError("unexpected quote in unquoted field")
                i += 1
            fields.append(s[start:i])
            if i < n:
                i += 1
                if i == n:
                    fields.append('')
                    break
            else:
                break
    return fields
```

